<h2 id="conventions-to-follow-while-creating-errors">Conventions to follow while creating errors</h2>

<ol>
  <li>Errors names and codes are namespaced to components, i.e. they need to be unique within a component, which is verified by this tool.</li>
  <li>Errors are not to be reused across components and modules.</li>
  <li>Error codes are not to be set as integer. CI will take care of updating Error codes from a string to an integer.</li>
  <li>Running <code class="language-plaintext highlighter-rouge">make error</code> analyzes your code and returns any warnings to be aware of.</li>
  <li>Capitalize the first letter of the every error description.</li>
  <li>Using errors.NewDefault(…) is deprecated. This tool emits a warning if its use is detected.</li>
  <li>Use errors.New(…) from MeshKit to create actual errors with all the details.
  This is often done in a factory function. It is important that the error code variable is used here, not a literal.
  Specify detailed descriptions, probable causes, and remedies. They need to be string literals, call expressions are ignored.
  This tool extracts this information from the code and exports it.
  For the Code argument in the errors.New use the same Error name and append a “Code” after it. e.g error name : ErrApplyManifest then the error code is ErrApplyManifestCode</li>
  <li>Set the value to any string, like “replace_me” (no convention here), e.g. ErrApplyManifestCode = “replace_me”.</li>
  <li>By convention, error codes and the factory functions live in files called error.go. The tool checks all files, but updates only error.go files.</li>
</ol>

<p>Use the <code class="language-plaintext highlighter-rouge">errors.New()</code> function to create a new instance of the error object and pass situation-specific attributes as function arguments. These attributes are:</p>

<ul>
  <li>Code</li>
  <li>Short Description</li>
  <li>Long Description</li>
  <li>Probable Cause</li>
  <li>Suggested Remediation</li>
</ul>

<h3 id="syntax">Syntax</h3>

<pre class="codeblock-pre" style="font-size: 1.75rem !important;">
<div class="codeblock">
<code class="clipboardjs">errors.New(ErrExampleCode, errors.Alert, []string{&quot;&lt;short-description&gt;&quot;}, []string{&quot;&lt;long-description&gt;&quot;}, []string{&quot;&lt;probable-cause&gt;&quot;}, []string{&quot;&lt;suggested remediation&gt;&quot;})</code>
</div>
</pre>
<h2 id="example">Example</h2>

<p>In this example we are creating an Error for being unable to marshal JSON</p>

<pre class="codeblock-pre" style="font-size: 1.75rem !important;">
<div class="codeblock">
<code class="clipboardjs">var (
	// Error code
    ErrMarshalCode= &quot;replace_me&quot;

    //Static errors (for example)
    ErrExample = errors.New(ErrExampleCode, errors.Alert, []string{&quot;&lt;short-description&gt;&quot;}, []string{&quot;&lt;long-description&gt;&quot;}, []string{&quot;&lt;probable-cause&gt;&quot;}, []string{&quot;&lt;suggested remediation&gt;&quot;})
)

// Dynamic errors
//Error Name
func ErrMarshal(err error, obj string) error {
	return errors.New(ErrMarshalCode, errors.Alert, []string{&quot;Unable to marshal the : &quot;, obj}, []string{err.Error()}, []string{}, []string{})
}</code>
</div>
</pre>

<h3 id="replacing-old-error-codes">Replacing old Error Codes</h3>

<p>Old</p>

<pre class="codeblock-pre" style="font-size: 1.75rem !important;">
<div class="codeblock">
<code class="clipboardjs">bd, err := json.Marshal(providers)
	if err != nil {
		http.Error(w, &quot;unable to marshal the providers&quot;, http.StatusInternalServerError)
		return
	}</code>
</div>
</pre>

<p>New</p>

<pre class="codeblock-pre" style="font-size: 1.75rem !important;">
<div class="codeblock">
<code class="clipboardjs">bd, err := json.Marshal(providers)
  if err != nil {
          obj := &quot;provider&quot;
          http.Error(w, ErrMarshal(err, obj).Error(), http.StatusInternalServerError)
          return
      }</code>
</div>
</pre>

<h2 id="replacing-logrus">Replacing logrus</h2>

<p>There already exists an <a href="https://github.com/meshery/meshkit/blob/master/logger/logger.go">interface for logger</a> in MeshKit.<br /><br /></p>

<div class="alert alert-warning">
<h4 class="alert-heading">WARNING</h4>
To enforce the use of meshkit errors, meshkit logger was designed such that it only works with meshkit errors. If a non-meshkit error is logged through the logger, it would panic and kill the process. See: <a href="https://github.com/meshery/meshkit/pull/119">meshkit#119</a> for more insight.
</div>

<h4 id="defining-a-logger">Defining a Logger</h4>

<pre class="codeblock-pre" style="font-size: 1.75rem !important;">
<div class="codeblock">
<code class="clipboardjs">type Logger struct {
	log   logger.Handler
}</code>
</div>
</pre>

<h4 id="debug">Debug</h4>

<h5 id="old">Old</h5>

<pre class="codeblock-pre" style="font-size: 1.75rem !important;">
<div class="codeblock">
<code class="clipboardjs">logrus.Debugf(&quot;meshLocationURL: %s&quot;, meshLocationURL)</code>
</div>
</pre>

<h5 id="new">New</h5>

<pre class="codeblock-pre" style="font-size: 1.75rem !important;">
<div class="codeblock">
<code class="clipboardjs">l.log.Debug(&quot;meshLocationURL: &quot;, meshLocationURL)</code>
</div>
</pre>

<h4 id="error">Error</h4>

<h5 id="old-1">Old</h5>

<pre class="codeblock-pre" style="font-size: 1.75rem !important;">
<div class="codeblock">
<code class="clipboardjs">logrus.Errorf(&quot;error marshaling data: %v.&quot;, err)</code>
</div>
</pre>

<h5 id="new-1">New</h5>

<pre class="codeblock-pre" style="font-size: 1.75rem !important;">
<div class="codeblock">
<code class="clipboardjs">l.log.Error(ErrMarshal(err, obj))</code>
</div>
</pre>

<h2 id="a-small-program-using-meshkit-errors-and-logger">A small program using meshkit errors and logger</h2>

<pre class="codeblock-pre" style="font-size: 1.75rem !important;">
<div class="codeblock">
<code class="clipboardjs">package main

import (
	&quot;fmt&quot;
	&quot;os&quot;

	meshkitErrors &quot;github.com/meshery/meshkit/errors&quot;
	&quot;github.com/meshery/meshkit/logger&quot;
	&quot;github.com/sirupsen/logrus&quot;
	&quot;github.com/spf13/viper&quot;
)

var (
	// CI will replace `test_code` with new error code
	ErrOpeningFileCode = &quot;test_code&quot;
)

func main() {
	logLevel := viper.GetInt(&quot;LOG_LEVEL&quot;)
	if viper.GetBool(&quot;DEBUG&quot;) {
		logLevel = int(logrus.DebugLevel)
	}
	log, err := logger.New(&quot;test&quot;, logger.Options{
		Format:   logger.SyslogLogFormat,
		LogLevel: logLevel,
	})
	if err != nil {
		fmt.Println(err)
		os.Exit(1)
	}

	// logging meshkit error
	err = openFileWithMeshkitError(&quot;some.txt&quot;)
	if err != nil {
		log.Error(err)
	}
	// OUTPUT
	// ERRO[2021-11-10T17:31:28+05:30] open some.txt: no such file or directory
	// app=test code=1001 probable-cause=&quot;empty string passed as argument .file with this name doesn&#39;t exist&quot;
	// severity=2 short-description=&quot;unable to open file&quot; suggested-remediation=&quot;pass a non-empty string as
	// filename .create file before opening it&quot;

	// logging non meshkit error
	err = openFile(&quot;some.txt&quot;)
	if err != nil {
		log.Error(err)
	}
	// OUTPUT
	// ERRO[2024-07-01T19:09:09+05:30] open some.txt: no such file or directory
	// app=test code= probable-cause= severity=0 short-description= suggested-remediation=

}

// this returns a non meshkit error
func openFile(name string) error {
	_, err := os.Open(name)
	return err
}

// this returns a meshkit error
func openFileWithMeshkitError(name string) error {
	_, err := os.Open(name)
	return ErrOpeningFile(err)
}

func ErrOpeningFile(err error) error {
	return meshkitErrors.New(ErrOpeningFileCode, meshkitErrors.Alert, []string{&quot;unable to open file&quot;},
		[]string{err.Error()},
		[]string{&quot;empty string passed as argument &quot;, &quot;file with this name doesn&#39;t exist&quot;},
		[]string{&quot;pass a non-empty string as filename &quot;, &quot;create file before opening it&quot;})
}</code>
</div>
